{
  "headline": "FDA's records trace our supply to a plant classified OAI 58 days before the shortage posting",
  "headline_cites": ["D9"],
  "sentences": [
    {
      "text": "FDA first posted the morphine sulfate injection shortage on 2017-10-31 and it remains current as of 2026-10-21, spanning 108 months on the list.",
      "cites": ["E45", "D13"]
    },
    {
      "text": "The Fresenius Kabi USA, LLC plant (FEI 3001833549) received an OAI classification letter dated 2017-12-28, which was 58 days after the initial shortage posting.",
      "cites": ["D9", "E21"]
    },
    {
      "text": "That same plant had a prior OAI inspection ending 2011-07-08 and another OAI inspection ending 2013-01-11, with a Warning Letter issued 2012-02-22.",
      "cites": ["E21", "E24", "E31"]
    },
    {
      "text": "The most recent inspection of the Fresenius Kabi plant ended 2023-10-13 and was classified VAI.",
      "cites": ["E30", "E32"]
    },
    {
      "text": "Hikma Pharmaceuticals USA Inc. (FEI 2220525) is also listed as a current shortage manufacturer; its latest inspection ended 2024-06-12 and was classified VAI.",
      "cites": ["E40", "E17", "E18"]
    },
    {
      "text": "Corvale East has 11 days on hand, Corvale General has 19 days, and Corvale Lakeside has 22 days of morphine sulfate at current usage rates.",
      "cites": ["D1", "D2", "D3"]
    },
    {
      "text": "The approved therapeutic interchange is the same product from Fresenius Kabi USA, LLC (NDC 63323045201, 2 mg/mL), approved by Casey Nguyen, MD on 2025-10-09, requiring pharmacist substitution.",
      "cites": ["D10", "E47"]
    }
  ]
}
